// ❌ OLD: Spawning a child process at runtime to get git metadata
// slows down server cold boot and fails if git is not installed in the Docker image.
const { execSync } = require('child_process');

export function getVersion() {
  return execSync('git rev-parse --short HEAD').toString().trim();
}

// ✅ NEW: Macro runs once at build time and inlines the string directly into code!
import { getGitCommit } from './git-macro.ts' with { type: 'macro' };

// Compiled output becomes: const commit = "a1b2c3d"; (ZERO runtime cost!)
export const CURRENT_COMMIT = getGitCommit();

